func _ready() -> void:
	_destino = ponto_b

func _physics_process(_delta: float) -> void:
	if global_position.distance_to(_destino) < 4.0:
		_destino = ponto_a if _destino == ponto_b else ponto_b
	velocity = (_destino - global_position).normalized() * speed
	move_and_slide()

