func _process(delta: float) -> void:
	if _inv > 0.0:
		_inv -= delta
		modulate.a = 0.4 if int(_inv * 12) % 2 == 0 else 1.0
	else:
		modulate.a = 1.0

func tentar_dano(qtd: int) -> bool:
	if _inv > 0.0:
		return false
	_inv = tempo_invencivel
	return true

