signal fase_mudou(fase: int)

@export var vida_maxima: int = 300
var vida: int
var fase: int = 1

func _ready() -> void:
	vida = vida_maxima

func receber_dano(qtd: int) -> void:
	vida = max(0, vida - qtd)
	var frac := float(vida) / float(vida_maxima)
	var nova_fase := 3 if frac <= 0.33 else (2 if frac <= 0.66 else 1)
	if nova_fase != fase:
		fase = nova_fase
		fase_mudou.emit(fase)

