const CAMINHO := "user://save.json"

func salvar(dados: Dictionary) -> void:
	var f := FileAccess.open(CAMINHO, FileAccess.WRITE)
	if f:
		f.store_string(JSON.stringify(dados))

func carregar() -> Dictionary:
	if not FileAccess.file_exists(CAMINHO):
		return {}
	var f := FileAccess.open(CAMINHO, FileAccess.READ)
	var dados = JSON.parse_string(f.get_as_text())
	return dados if dados is Dictionary else {}

extends Node

