@export var raio: float = 300.0

func _ready() -> void:
	var t := Timer.new()
	t.wait_time = intervalo
	t.autostart = true
	add_child(t)
	t.timeout.connect(_spawnar)

func _spawnar() -> void:
	if cena == null:
		return
	var inst := cena.instantiate()
	inst.global_position = global_position + Vector2.RIGHT.rotated(randf() * TAU) * raio
	get_tree().current_scene.add_child(inst)

extends Node

@export var cena: PackedScene
@export var tamanho: int = 30
var _pool: Array[Node] = []

func _ready() -> void:
	for i in tamanho:
		var n := cena.instantiate()
		n.set_process(false)
		n.hide()
		add_child(n)
		_pool.append(n)

func pegar() -> Node:
	for n in _pool:
		if not n.visible:
			n.show()
			n.set_process(true)
			return n
	return null

extends Node2D

